#!/usr/bin/env node
// Copies the content playbooks into the Slack agent's instructions, so people and the bot follow
// the same rules. Run after editing agents/skills/{new-event,edit-event}/SKILL.md:
//   node tools/build-agent-prompt.mjs
// packages/agent/test/prompt.test.ts fails when the generated file is out of date.
import { readFileSync, writeFileSync } from 'node:fs';

export const PLAYBOOK_NAMES = ['new-event', 'edit-event'];

export function generated(root = new URL('..', import.meta.url)) {
  const body = PLAYBOOK_NAMES.map((n) =>
    readFileSync(new URL(`agents/skills/${n}/SKILL.md`, root), 'utf8')
      .replace(/^---[\s\S]*?---\n+/, '')
      .trim(),
  ).join('\n\n');
  return `// GENERATED by tools/build-agent-prompt.mjs from agents/skills/{${PLAYBOOK_NAMES.join(',')}}/SKILL.md. Do not edit.\nexport const PLAYBOOKS = ${JSON.stringify(body)};\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL('../packages/agent/src/playbooks.generated.ts', import.meta.url), generated());
  console.log('wrote packages/agent/src/playbooks.generated.ts');
}
